SELECT id, approval_type AS approvalType, target_type AS targetType, target_id AS targetId, applicant_id AS applicantId, approver_id AS approverId, approval_status AS approvalStatus, approval_remark AS approvalRemark, approved_at AS approvedAt, transferred_to AS transferredTo, created_at AS createdAt, updated_at AS updatedAt FROM approval_record WHERE approval_status = 'PENDING'
AND approver_id = #{approverId}
AND approval_type = #{approvalType}
AND target_type like concat('%', #{targetType}, '%')
AND approval_status = #{approvalStatus}

SELECT id, approval_type AS approvalType, target_type AS targetType, target_id AS targetId, applicant_id AS applicantId, approver_id AS approverId, approval_status AS approvalStatus, approval_remark AS approvalRemark, approved_at AS approvedAt, transferred_to AS transferredTo, created_at AS createdAt, updated_at AS updatedAt FROM approval_record WHERE approval_status != 'PENDING'
AND approver_id = #{approverId}
AND approval_type = #{approvalType}
AND target_type like concat('%', #{targetType}, '%')
AND approval_status = #{approvalStatus}
ORDER BY approved_at DESC
